svg.script:


// Funcionalidad básica para Canvas Apps
(function() {

  // Configuración
  const canvasActions = {
    'logo-click': 'navigate_home',
    'nav-inicio': 'navigate_inicio', 
    'nav-acerca': 'navigate_acerca',
    'nav-servicios': 'navigate_servicios',
    'nav-blog': 'navigate_blog',
    'nav-contacto': 'navigate_contacto',
    'header-cta-click': 'explore_guitars_header',
    'main-cta-click': 'explore_guitars_main',
    'image-click': 'view_guitar_details'
  };

  // Agregar event listeners
  Object.keys(canvasActions).forEach(elementId => {
    const element = document.getElementById(elementId);
    if (element) {
      element.addEventListener('click', function() {
        const action = canvasActions[elementId];
        triggerCanvasAction(action, elementId);
      });

      // Hover effects
      element.addEventListener('mouseenter', function() {
        this.style.opacity = '0.7';
      });

      element.addEventListener('mouseleave', function() {
        this.style.opacity = '1';
      });
    }
  });

  // Función para comunicar con Canvas
  function triggerCanvasAction(action, elementId) {
    console.log('SVG Canvas Action:', action, 'Element:', elementId);

    // PostMessage para Canvas Apps
    if (window.parent && window.parent.postMessage) {
      window.parent.postMessage({
        type: 'SVG_CANVAS_ACTION',
        action: action,
        element: elementId,
        timestamp: new Date().toISOString(),
        source: 'guitar-luthier-svg'
      }, '*');
    }

    // LocalStorage para persistencia
    localStorage.setItem('lastSVGAction', JSON.stringify({
      action: action,
      element: elementId,
      timestamp: new Date().toISOString()
    }));

    // Feedback visual
    showSVGFeedback(action);
  }

  // Feedback visual en SVG
  function showSVGFeedback(action) {
    // Crear elemento de feedback
    const svg = document.querySelector('svg');
    const feedback = document.createElementNS('http://www.w3.org/2000/svg', 'text');

    feedback.setAttribute('x', '600');
    feedback.setAttribute('y', '750');
    feedback.setAttribute('text-anchor', 'middle');
    feedback.setAttribute('font-family', 'Arial, sans-serif');
    feedback.setAttribute('font-size', '16');
    feedback.setAttribute('font-weight', '500');
    feedback.setAttribute('fill', '#4ecdc4');
    feedback.setAttribute('opacity', '0');
    feedback.textContent = `Acción: ${action}`;

    svg.appendChild(feedback);

    // Animación de aparición
    feedback.style.transition = 'opacity 0.3s ease';
    setTimeout(() => feedback.setAttribute('opacity', '1'), 100);

    // Auto remove
    setTimeout(() => {
      feedback.style.transition = 'opacity 0.3s ease';
      feedback.setAttribute('opacity', '0');
      setTimeout(() => feedback.remove(), 300);
    }, 2000);
  }

  // API pública para Canvas
  window.SVGGuitarApp = {
    getLastAction: () => JSON.parse(localStorage.getItem('lastSVGAction') || '{}'),
    performAction: (action) => triggerCanvasAction(action, 'programmatic'),
    updateContent: (updates) => {
      // Actualizar texto dinámicamente
      if (updates.title) {
        // Actualizar título si es necesario
        console.log('Updating title:', updates.title);
      }
      if (updates.description) {
        // Actualizar descripción si es necesario
        console.log('Updating description:', updates.description);
      }
    }
  };

  // Notificar a Canvas que el SVG está listo
  setTimeout(() => {
    if (window.parent && window.parent.postMessage) {
      window.parent.postMessage({
        type: 'SVG_READY',
        timestamp: new Date().toISOString(),
        capabilities: ['click-tracking', 'visual-feedback', 'programmatic-actions']
      }, '*');
    }
  }, 100);

})();
